messages.content:
Tool response:
Tool: create_lead
Description: Create Lead
Parameters:
    {
      "type": "object",
      "properties": {
        "customer_name": {
          "type": "string",
          "title": "Customer Name",
          "description": "Full name of the customer"
        },
        "customer_phone": {
          "type": "string",
          "title": "Customer Phone",
          "description": "Phone number of the customer"
        },
        "customer_email": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Customer Email",
          "description": "Email address of the customer"
        },
        "vehicle_interest": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Vehicle Interest",
          "description": "Specific vehicle the customer is interested in"
        },
        "source": {
          "type": "string",
          "title": "Source",
          "description": "Source of the lead (e.g., Walk-in, Phone, Website)"
        },
        "assigned_to": {
          "type": "integer",
          "title": "Assigned To",
          "description": "ID of the salesperson to whom the lead is assigned"
        }
      },
      "required": [
        "customer_name",
        "customer_phone",
        "source",
        "assigned_to"
      ]
    }
